# owner: platform
from typing import Iterable, List, Tuple

from rosterkit.models import Student


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Aligned text rows, sorted by name."""
    roster = list(students)
    roster.sort(key=lambda item: item.display_name)
    if not roster:
        raise ValueError("no students to list")
    _check_emails(roster)
    return _align_rows(roster)


def _check_emails(roster: List[Student]) -> None:
    for student in roster:
        if not student.email:
            text = f"no email for {student.display_name}"
            raise ValueError(text)


def _align_rows(roster: List[Student]) -> List[str]:
    name_width, section_width = _widths(roster)
    return [
        f"{item.display_name:<{name_width}}  "
        f"{item.section:<{section_width}}  {item.email}"
        for item in roster
    ]


def _widths(roster: List[Student]) -> Tuple[int, int]:
    names = [item.display_name for item in roster]
    sections = [item.section for item in roster]
    return max(map(len, names)), max(map(len, sections))
